"""`Eyeline card`: generated by export_nodes.py from face_cards.blend; kept by hand from then on."""

NAME = 'Eyeline card'


def build(lib):
    t = lib.new_material(NAME, props={
            'use_backface_culling': True,
        })

    t.node('ShaderNodeOutputMaterial', 'Material Output', props={
        'location': (1343.6343, -190.27199),
    })
    t.node('ShaderNodeTexImage', 'tex.eyeline_lower', props={
        'location': (653.9276, -141.98618),
        'label': 'tex.eyeline_lower',
        'extension': 'CLIP',
    })
    t.node('ShaderNodeTexImage', 'tex.eyeline_upper', props={
        'location': (653.9276, -491.98618),
        'label': 'tex.eyeline_upper',
        'extension': 'CLIP',
    })
    t.node('ShaderNodeGroup', 'Group', props={
        'node_tree': lib.group('.eyeline sticker'),
        'location': (1072.8446, -178.0918),
        'width': 190.52356,
    })
    t.node('ShaderNodeTexImage', 'tex.eyeline_shadow', props={
        'location': (653.9276, 208.01382),
        'label': 'tex.eyeline_shadow',
        'show_texture': True,
    })

    t.link('tex.eyeline_lower', 'Alpha', 'Group', 0)
    t.link('tex.eyeline_lower', 'Color', 'Group', 3)
    t.link('tex.eyeline_upper', 'Alpha', 'Group', 4)
    t.link('tex.eyeline_upper', 'Color', 'Group', 5)
    t.link('Group', 'Shader', 'Material Output', 'Surface')
    t.link('tex.eyeline_shadow', 'Color', 'Group', 2)
    t.link('tex.eyeline_shadow', 'Alpha', 'Group', 1)
    return t
